CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE subject(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL, code varchar(255) NOT NULL UNIQUE, credits integer NOT NULL CHECK(credits BETWEEN 1 AND 30));
CREATE TABLE teacher(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL, email varchar(255) NOT NULL UNIQUE, department varchar(255) NOT NULL);
CREATE TABLE teacher_subject(teacher_id bigint REFERENCES teacher(id), subject_id bigint REFERENCES subject(id), PRIMARY KEY(teacher_id,subject_id));
CREATE TABLE study_group(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL UNIQUE, study_year integer NOT NULL CHECK(study_year BETWEEN 1 AND 6), curator_id bigint NOT NULL REFERENCES teacher(id));
CREATE TABLE group_subject(group_id bigint REFERENCES study_group(id), subject_id bigint REFERENCES subject(id), PRIMARY KEY(group_id,subject_id));
CREATE TABLE student(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, first_name varchar(255) NOT NULL, last_name varchar(255) NOT NULL, student_no varchar(255) NOT NULL UNIQUE, email varchar(255) NOT NULL UNIQUE, phone varchar(255), group_id bigint NOT NULL REFERENCES study_group(id));
CREATE TABLE room(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL UNIQUE, building varchar(255) NOT NULL, capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 1000));
CREATE TABLE semester(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL, start_date date NOT NULL, end_date date NOT NULL, status varchar(255) NOT NULL CHECK(status IN ('active','archived')), CHECK(start_date<end_date));
CREATE TABLE app_user(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, name varchar(255) NOT NULL, email varchar(255) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, role varchar(255) NOT NULL CHECK(role IN ('ADMIN','TEACHER','STUDENT','STAFF')), student_id bigint UNIQUE REFERENCES student(id), teacher_id bigint UNIQUE REFERENCES teacher(id), enabled boolean NOT NULL DEFAULT true, CHECK((role='STUDENT' AND student_id IS NOT NULL AND teacher_id IS NULL) OR (role='TEACHER' AND teacher_id IS NOT NULL AND student_id IS NULL) OR (role IN ('ADMIN','STAFF') AND student_id IS NULL AND teacher_id IS NULL)));
CREATE UNIQUE INDEX user_email_lower ON app_user(lower(email));
CREATE UNIQUE INDEX student_email_lower ON student(lower(email));
CREATE UNIQUE INDEX teacher_email_lower ON teacher(lower(email));
CREATE TABLE lesson(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, lesson_date date NOT NULL, start_time time NOT NULL, end_time time NOT NULL, semester_id bigint NOT NULL REFERENCES semester(id), group_id bigint NOT NULL REFERENCES study_group(id), subject_id bigint NOT NULL REFERENCES subject(id), teacher_id bigint NOT NULL REFERENCES teacher(id), room_id bigint NOT NULL REFERENCES room(id), topic varchar(255), status varchar(255) NOT NULL CHECK(status IN ('scheduled','conducted','cancelled')), CHECK(start_time<end_time));
ALTER TABLE lesson ADD CONSTRAINT teacher_overlap EXCLUDE USING gist(teacher_id WITH =, tsrange(lesson_date+start_time,lesson_date+end_time,'[)') WITH &&) WHERE(status<>'cancelled');
ALTER TABLE lesson ADD CONSTRAINT room_overlap EXCLUDE USING gist(room_id WITH =, tsrange(lesson_date+start_time,lesson_date+end_time,'[)') WITH &&) WHERE(status<>'cancelled');
ALTER TABLE lesson ADD CONSTRAINT group_overlap EXCLUDE USING gist(group_id WITH =, tsrange(lesson_date+start_time,lesson_date+end_time,'[)') WITH &&) WHERE(status<>'cancelled');
CREATE TABLE attendance(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, student_id bigint NOT NULL REFERENCES student(id), lesson_id bigint NOT NULL REFERENCES lesson(id), status varchar(255) NOT NULL CHECK(status IN ('present','late','absent','excused')), updated_at timestamp with time zone NOT NULL, UNIQUE(student_id,lesson_id));
CREATE TABLE grade(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, student_id bigint NOT NULL REFERENCES student(id), lesson_id bigint NOT NULL REFERENCES lesson(id), type varchar(255) NOT NULL CHECK(type IN ('Текущая','Рубежная','Итоговая')), score integer NOT NULL CHECK(score BETWEEN 0 AND 100), updated_at timestamp with time zone NOT NULL, UNIQUE(student_id,lesson_id,type));
CREATE TABLE lesson_review(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, lesson_id bigint NOT NULL REFERENCES lesson(id), reviewer_id bigint NOT NULL REFERENCES app_user(id), result varchar(255) NOT NULL CHECK(result IN ('confirmed','issue','pending')), note varchar(2000) NOT NULL, updated_at timestamp with time zone NOT NULL);
CREATE TABLE audit_event(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, at timestamp with time zone NOT NULL, actor varchar(255) NOT NULL, action varchar(255) NOT NULL, entity varchar(255) NOT NULL, description varchar(2000) NOT NULL);
CREATE TABLE access_session(id bigserial PRIMARY KEY, version bigint NOT NULL DEFAULT 0, token_hash varchar(255) NOT NULL UNIQUE, user_id bigint NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, expires_at timestamp with time zone NOT NULL);
CREATE INDEX lesson_teacher_date ON lesson(teacher_id,lesson_date);
CREATE INDEX student_group ON student(group_id);
CREATE INDEX grade_student ON grade(student_id);
CREATE INDEX attendance_lesson ON attendance(lesson_id);
CREATE INDEX audit_at ON audit_event(at);
